/*
 * A231873  Elements of the integer compositions sub-operad Comp of TN_2
 *          generated by 00 and 010.
 * https://oeis.org/A231873
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) records the n-th binary word over {1,2} that starts with 1
 *            in lexicographic order, interpreted as a decimal integer. The
 *            word is obtained by writing the binary expansion of (n -
 *            2^(⌊log₂ n⌋)) and mapping 0 → 1, 1 → 2, with a leading 1
 * Range:     u8 n <= 7, u16 n <= 31, u32 n <= 31, u64 n <= 31, u128 n <= 31,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* compute the length L of the word:  L = floor_log2(n) + 1  */
    idx_t temp = n;
    idx_t L = 0;
    while (temp > 0) {
        temp >>= 1;
        ++L;
    }

    /* offset within the block of length L (0‑based) */
    idx_t offset = n - ((idx_t)1 << (L - 1));

    /* build the decimal value */
    seq_t value = 1;   /* leading '1' */
    for (idx_t p = 0; p < L - 1; ++p) {
        idx_t bit_pos = L - 2 - p;            /* most significant bit first */
        seq_t digit = ((offset >> bit_pos) & 1) ? 2 : 1;
        value = value * 10 + digit;
    }
    return value;
}
